// Renders the interactive Observability Requirements Table using Tabulator.
// Looks for a <div id="orf-requirements-table"> on the page and populates it
// from docs/assets/requirements.json (generated by scripts/build_json.py).

function __orfReadyTable(fn) {
  if (document.readyState !== "loading") fn();
  else document.addEventListener("DOMContentLoaded", fn);
}

__orfReadyTable(function () {
  var el = document.getElementById("orf-requirements-table");
  if (!el || typeof Tabulator === "undefined") return;

  // Derive the JSON URL from this script's own (browser-resolved, absolute) src.
  // This is correct regardless of page depth and works on GitHub Pages subpaths.
  var self = document.querySelector('script[src$="javascripts/requirements-table.js"]');
  var siteRoot = self
    ? self.src.replace(/javascripts\/.*$/, "")
    : "/";
  var dataUrl = siteRoot + "assets/requirements.json";

  var tierFormatter = function (cell) {
    var v = cell.getValue();
    return '<span class="orf-tier orf-tier-' + v + '">Tier ' + v + "</span>";
  };

  var actionFormatter = function (cell) {
    var v = (cell.getValue() || "").toLowerCase();
    var cls = "gth";
    if (v === "mandatory") cls = "mand";
    else if (v.indexOf("waivable") !== -1) cls = "waiv";
    return '<span class="orf-action orf-action-' + cls + '">' + cell.getValue() + "</span>";
  };

  new Tabulator(el, {
    ajaxURL: dataUrl,
    layout: "fitColumns",
    height: "720px",
    groupBy: "category_name",
    pagination: false,
    columns: [
      { title: "ID", field: "id", width: 110, headerFilter: "input" },
      { title: "Telemetry Item", field: "name", widthGrow: 3, headerFilter: "input", formatter: "textarea" },
      { title: "Type", field: "type", width: 90, headerFilter: "list",
        headerFilterParams: { values: { "": "All", metric: "metric", log: "log", trace: "trace" } } },
      { title: "Tier", field: "tier", width: 90, formatter: tierFormatter, headerFilter: "list",
        headerFilterParams: { values: { "": "All", 1: "Tier 1", 2: "Tier 2", 3: "Tier 3", 4: "Tier 4" } } },
      { title: "High-Risk", field: "high", width: 150, formatter: actionFormatter },
      { title: "Medium-Risk", field: "medium", width: 170, formatter: actionFormatter },
      { title: "Low-Risk", field: "low", width: 130, formatter: actionFormatter },
    ],
    rowClick: function (e, row) {
      var d = row.getData();
      alert(
        d.id + " — " + d.name +
        "\n\nDefinition: " + d.definition +
        "\n\nRisk: " + d.risk +
        "\nImpact: " + d.impact +
        "\nMitigations: " + d.mitigations
      );
    },
  });
});
